package com.aaliyun.leadnews.wemedia.domain;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;class WmNewsStatusTest{@Test void onlyDraftAndRejectedAreEditable(){assertThat(WmNewsStatus.DRAFT.editable()).isTrue();assertThat(WmNewsStatus.REJECTED.editable()).isTrue();assertThat(WmNewsStatus.SUBMITTED.editable()).isFalse();assertThat(WmNewsStatus.MANUAL_REVIEW.editable()).isFalse();}@Test void auditTransitionsAreExplicit(){assertThat(WmNewsStatus.DRAFT.canTransitionTo(WmNewsStatus.SUBMITTED)).isTrue();assertThat(WmNewsStatus.SUBMITTED.canTransitionTo(WmNewsStatus.AUDITING)).isTrue();assertThat(WmNewsStatus.AUDITING.canTransitionTo(WmNewsStatus.APPROVED)).isTrue();assertThat(WmNewsStatus.AUDITING.canTransitionTo(WmNewsStatus.REJECTED)).isTrue();assertThat(WmNewsStatus.AUDITING.canTransitionTo(WmNewsStatus.MANUAL_REVIEW)).isTrue();assertThat(WmNewsStatus.MANUAL_REVIEW.canTransitionTo(WmNewsStatus.APPROVED)).isTrue();assertThat(WmNewsStatus.APPROVED.canTransitionTo(WmNewsStatus.WAITING)).isTrue();assertThat(WmNewsStatus.APPROVED.canTransitionTo(WmNewsStatus.REJECTED)).isFalse();}}
